/** Spec §3.6: lowercase `[a-z0-9]+`; other chars → `_`; collapse. */
function billedPartySlug(raw: string): string {
  return raw
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_|_$/g, '');
}

