  private buildInvoiceSnapshotSync(input: {
    invoiceId: string;
    invoiceNumber: string;
    invoiceDate: string;
    propertyId: string;
    reservationId: string;
    folioWindowId: string;
    generatedAt: number;
    autoGenerated: boolean;
    buyer: InvoiceBuyerWire | null;
  }): Record<string, unknown> {
    const reservationRows = this.ctx.storage.sql
      .exec(
        `SELECT guest_ref, pii_key_id, arrival_date, departure_date, room_id, rate_plan_id, status, promo_id
         FROM reservation WHERE reservation_id = ?`,
        input.reservationId,
      )
      .toArray() as Array<{
      guest_ref: string;
      pii_key_id: string;
      arrival_date: string;
      departure_date: string;
      room_id: string | null;
      rate_plan_id: string | null;
      status: string;
      promo_id: string | null;
    }>;
    const reservation = reservationRows[0]!;

    const lineRows = this.ctx.storage.sql
      .exec(
        `SELECT folio_line_id, charge_code, amount_minor, ledger_amount_minor, txn_currency, fx_rate,
                business_date, source, tax_of, tax_rule_id, tax_component, payment_id, created_at
         FROM folio_line
         WHERE reservation_id = ? AND folio_window_id = ?
         ORDER BY created_at ASC`,
        input.reservationId,
        input.folioWindowId,
      )
      .toArray() as Array<{
      folio_line_id: string;
      charge_code: string;
      amount_minor: number;
      ledger_amount_minor: number;
      txn_currency: string;
      fx_rate: string;
      business_date: string | null;
      source: string | null;
      tax_of: string | null;
      tax_rule_id: string | null;
      tax_component: string | null;
      payment_id: string | null;
      created_at: number;
    }>;

    const chargeCodes = new Map<string, string>();
    const chargeTaxGroups = new Map<string, string | null>();
    for (const code of [...new Set(lineRows.map((row) => row.charge_code))]) {
      const ccRows = this.ctx.storage.sql
        .exec(`SELECT name, tax_group FROM charge_code WHERE code = ?`, code)
        .toArray() as Array<{ name: string; tax_group: string | null }>;
      chargeCodes.set(code, ccRows[0]?.name ?? code);
      chargeTaxGroups.set(code, ccRows[0]?.tax_group ?? null);
    }
    const classificationRaw = this.readConfigValueSync('pms.tax.classification');
    const classification =
      classificationRaw && typeof classificationRaw === 'object' && !Array.isArray(classificationRaw)
        ? (classificationRaw as Record<string, string>)
        : {};
    const lineById = new Map(lineRows.map((row) => [row.folio_line_id, row]));
    const hsnFor = (row: (typeof lineRows)[number]): string | null => {
      const parent = row.tax_of ? lineById.get(row.tax_of) : undefined;
      const code = parent?.charge_code ?? row.charge_code;
      const group = chargeTaxGroups.get(code);
      if (!group) return null;
      const hsn = classification[group];
      return typeof hsn === 'string' ? hsn : null;
    };

    const lines = lineRows.map((row) => ({
      folioLineId: row.folio_line_id,
      chargeCode: row.charge_code,
      chargeName: chargeCodes.get(row.charge_code) ?? row.charge_code,
      hsnSac: hsnFor(row),
      amountMinor: row.amount_minor,
      ledgerAmountMinor: row.ledger_amount_minor,
      txnCurrency: row.txn_currency,
      fxRate: row.fx_rate,
      businessDate: row.business_date,
      source: row.source,
      taxOf: row.tax_of,
      taxRuleId: row.tax_rule_id,
      taxComponent: row.tax_component ?? '',
      paymentId: row.payment_id,
    }));

    const taxSummaryMap = new Map<
      string,
      { taxRuleId: string; taxComponent: string; label: string; amountMinor: number }
    >();
    for (const row of lineRows) {
      if (row.source !== 'TAX' && !row.tax_of) continue;
      const taxRuleId = row.tax_rule_id ?? row.charge_code;
      const taxComponent = row.tax_component ?? '';
      const key = `${taxRuleId}:${taxComponent}:${row.charge_code}`;
      const bucket = taxSummaryMap.get(key) ?? {
        taxRuleId,
        taxComponent,
        label: chargeCodes.get(row.charge_code) ?? row.charge_code,
        amountMinor: 0,
      };
      bucket.amountMinor += row.ledger_amount_minor;
      taxSummaryMap.set(key, bucket);
    }

    let chargesMinor = 0;
    let taxMinor = 0;
    let paymentsMinor = 0;
    for (const row of lineRows) {
      if (row.source === 'TAX' || row.tax_of) {
        taxMinor += row.ledger_amount_minor;
      } else if (row.charge_code === 'PAYMENT') {
        paymentsMinor += row.ledger_amount_minor;
      } else {
        chargesMinor += row.ledger_amount_minor;
      }
    }
    const balanceMinor = lineRows.reduce((sum, row) => sum + row.ledger_amount_minor, 0);

    const invoiceDate = input.invoiceDate;

    const presentation = {
      title: this.readConfigValueSync('pms.invoice.title'),
      footer: this.readConfigValueSync('pms.invoice.footer'),
      showCompany: this.readConfigValueSync('pms.invoice.show_company'),
      showRoom: this.readConfigValueSync('pms.invoice.show_room'),
      showTaxfee: this.readConfigValueSync('pms.invoice.show_taxfee'),
      showDuedate: this.readConfigValueSync('pms.invoice.show_duedate'),
      showPackage: this.readConfigValueSync('pms.invoice.show_package'),
      compact: this.readConfigValueSync('pms.invoice.compact'),
      language: this.readConfigValueSync('pms.invoice.language'),
      guestLang: this.readConfigValueSync('pms.invoice.guest_lang'),
      titleLang: this.readConfigValueSync('pms.invoice.title_lang'),
    };

    const seller = sellerGstinFromRegistrations(this.readConfigValueSync('pms.tax.registrations'));
    const buyer =
      input.buyer == null
        ? null
        : input.buyer.type === 'REGISTERED'
          ? snapshotBusinessBuyer(input.buyer.fields)
          : {
              type: 'UNREGISTERED' as const,
              party: 'INDIVIDUAL' as const,
              buyerSnapshotId: input.buyer.buyerSnapshotId,
            };

    return {
      schemaVersion: 2,
      invoiceId: input.invoiceId,
      invoiceNumber: input.invoiceNumber,
      propertyId: input.propertyId,
      reservationId: input.reservationId,
      folioWindowId: input.folioWindowId,
      generatedAt: input.generatedAt,
      invoiceDate,
      guestRef: reservation.guest_ref,
      piiKeyId: reservation.pii_key_id,
      seller: { gstin: seller.gstin, stateCode: seller.stateCode },
      placeOfSupplyStateCode: seller.stateCode,
      buyer,
      reservation: {
        arrivalDate: reservation.arrival_date,
        departureDate: reservation.departure_date,
        roomId: reservation.room_id,
        ratePlanId: reservation.rate_plan_id,
        status: reservation.status,
        ...(reservation.promo_id ? { promoId: reservation.promo_id } : {}),
      },
      presentation,
      taxLocation: this.readConfigValueSync('pms.tax.location'),
      taxRegistrations: this.readConfigValueSync('pms.tax.registrations'),
      ledgerCurrency: this.readStoredLedgerCurrencySync(),
      lines,
      taxSummary: [...taxSummaryMap.values()],
      totals: { chargesMinor, taxMinor, paymentsMinor, balanceMinor },
      autoGenerated: input.autoGenerated,
    };
  }

