  /** Codes in `pms.housekeeping.task_types`, read inside the create/update transaction (R4.30 D3). */
  private housekeepingTaskTypesSync(): HousekeepingTaskType[] {
    const raw = this.readConfigValueSync('pms.housekeeping.task_types');
    if (!Array.isArray(raw)) return [];
    const out: HousekeepingTaskType[] = [];
    for (const t of raw) {
      const o = t as { code?: unknown; label?: unknown } | null;
      if (o && typeof o.code === 'string' && typeof o.label === 'string') {
        out.push({ code: o.code, label: o.label });
      }
    }
    return out;
  }

  private housekeepingTaskTypeCodesSync(): string[] {
    return this.housekeepingTaskTypesSync().map((t) => t.code);
  }

  /**
   * Shared write path for housekeeping tasks (R4.30). INTERACTIVE, pms.core-entitled,
   * FAIL_CLOSED; the key is per user at the DO boundary (`runIdempotent` scopes it).
   */
  private async runHousekeepingTaskWrite<R extends { ok: true }>(
    actor: ActorContext,
    idem: IdempotencyKey,
    audit: {
      commandId:
        | 'housekeeping.create_task'
        | 'housekeeping.update_task'
        | 'housekeeping.transition_task'
        | 'housekeeping.create_request'
        | 'housekeeping.update_request'
        | 'housekeeping.record_lost_item'
        | 'housekeeping.update_lost_item'
        | 'housekeeping.open_case'
        | 'housekeeping.update_case'
        | 'housekeeping.save_inspection_template'
        | 'housekeeping.record_inspection'
        | 'housekeeping.start_guest_audit'
        | 'housekeeping.record_guest_audit_count'
        | 'housekeeping.close_guest_audit'
        | 'housekeeping.record_linen_movement'
        | 'housekeeping.record_minibar_pickup'
        | 'housekeeping.save_amenity'
        | 'housekeeping.save_amenity_rule'
        | 'housekeeping.plan_amenity_dispatches'
        | 'housekeeping.confirm_amenity_dispatch';
      /** Permission the route needs; housekeeping:write unless the command is a setting. */
      permission?: 'housekeeping:write' | 'settings:configure';
      entityId?: string;
      /** Audit entity type; tasks by default. */
      entityType?: string;
      /** Stay the audit row belongs to (the minibar pickup), so the folio audit trail finds it. */
      reservationId?: string;
      /** Staff ref to verify against the roster before the transaction opens. */
      assigneeRef?: string | null;
      /** Roster kind the assignee must hold (R4.11 requests); housekeeper by default. */
      assigneeKind?: 'housekeeper' | 'maintenance';
      /** R4.11: the assignee must also be linked to this property. */
      scopeAssigneeToProperty?: boolean;
      /** R4.11 refs checked in the org before the transaction opens. */
      refGates?: (orgId: string, propertyId: string) => Promise<HousekeepingRefGateFailure | null>;
    },
    execute: (
      ctx: ModuleTxnCtx,
      actorRef: string,
    ) => { result: R; entityId: string; before: unknown | null; after: unknown },
  ): Promise<
    | R
    | { ok: false; error: typeof IDEM_KEY_REUSED }
    | { ok: false; error: typeof ENTITLEMENT_REQUIRED | typeof ENTITLEMENT_UNAVAILABLE }
    | { ok: false; error: typeof FORBIDDEN | typeof NOT_MEMBER }
    | { ok: false; error: typeof PROPERTY_ID_UNSET }
    | { ok: false; error: typeof ORG_ID_UNSET }
    | { ok: false; error: typeof NOT_FOUND }
    | HousekeepingRefGateFailure
    | { ok: false; error: typeof INTERNAL_ERROR }
    | NonNullable<ReturnType<typeof mapPropertyCommandError>>
  > {
    this.assertRpcAvailable();
    this.lanes.touchInteractive();
    const orgId = this.getOrgIdSync();
    if (!orgId) return { ok: false, error: ORG_ID_UNSET };

    const permDenied = await this.gatePermission(actor, audit.permission ?? 'housekeeping:write');
    if (permDenied) return permDenied;

    const denied = await this.gateCoreEntitlement(orgId);
    if (denied) return denied;

    const propertyId = this.getPropertyIdSync();
    if (!propertyId) return { ok: false, error: PROPERTY_ID_UNSET };

    if (audit.assigneeRef !== undefined && audit.assigneeRef !== null) {
      if (!isStaffRef(audit.assigneeRef)) return { ok: false, error: INVALID_ASSIGNEE_REF };
      const staffGate = await this.gateStaffRef(
        orgId,
        audit.assigneeRef,
        audit.assigneeKind ?? 'housekeeper',
        audit.scopeAssigneeToProperty ? propertyId : undefined,
      );
      if (!staffGate.ok) return staffGate;
    }
    if (audit.refGates) {
      const refDenied = await audit.refGates(orgId, propertyId);
      if (refDenied) return refDenied;
    }

    const actorRef = this.auditActorSync(actor);
    try {
      return this.ctx.storage.transactionSync(() =>
        runIdempotent(this.ctx.storage.sql, idem, () => {
          const out = execute(this.moduleTxnCtx(orgId, propertyId), actorRef);
          this.appendAuditLogSync({
            actor: actorRef,
            commandId: audit.commandId,
            entityType: audit.entityType ?? 'housekeeping_task',
            entityId: out.entityId,
            beforeJson: out.before,
            afterJson: out.after,
            ...(audit.reservationId ? { reservationId: audit.reservationId } : {}),
          });
          return out.result as Sync<R>;
        }, actor),
      );
    } catch (e) {
      if (e instanceof IdempotencyKeyReused) return { ok: false, error: IDEM_KEY_REUSED };
      if (e instanceof InvalidAssigneeRefError) return { ok: false, error: INVALID_ASSIGNEE_REF };
      if (
        e instanceof HousekeepingRoomNotFoundError ||
        e instanceof HousekeepingRecordNotFoundError ||
        e instanceof RoomNotFoundError
      ) {
        return { ok: false, error: NOT_FOUND };
      }
      const mapped = mapPropertyCommandError(e);
      if (mapped) return mapped;
      return { ok: false, error: INTERNAL_ERROR };
    }
  }

